(*
需求原文：
In an industrial water supply system, there are 5 pumps, each of which can be controlled independently. The system needs to support both manual and automatic operating modes.
Based on the value of the mode variable, switch to the corresponding operating mode.
In manual mode, control the start and stop of the selected pump based on the value of pumpGroup[1..5].selection.
In automatic mode, compare the priority of each pump, and automatically select the 3 pumps with higher priority for water supply according to the method of three in use and two on standby.

扫描周期：20 ms。

接口字段映射：
priority、selection、RunComd 为 ST_Pump 字段。
仅写 pumpGroup[1..5].RunComd，不写 priority 或 selection。

形式化规约：
C1: G(stop -> !RunComd)
C2: G(RunComd -> !stop)
C4: G(!(start && stop))
C6: G(RunComd -> (RunComd W stop))
C10: G[0,1](!RunComd)

语义冲突报告（待审，不声称全部规约已满足）：
1. C4 约束只读输入，功能块不能阻止 start 与 stop 同时有效；
   本实现对这种请求执行 stop 优先。
2. K2 的无条件自动运行三台与 stop、初态以及 start 启动许可冲突；
   本实现只在初始化结束、启动许可保持且无 stop 时运行三台。
3. C6 的逐泵保持要求与手动取消选择、模式切换及自动优先级重选冲突；
   本实现保持系统启动许可，但每周期按当前模式重新计算逐泵命令。
   因此，未收到 stop 时也可能因上述输入变化清除某台泵的命令。
4. C10 按闭区间扫描索引 [0,1] 实现为前两次调用全部停泵。
   初始化期间不锁存 start；初始化后 start 为 TRUE 即建立启动许可。

自动选择：优先级数值越大越优先；相同优先级按泵号升序。
没有基于真实编译器或逐周期测试的验证结论。
*)

TYPE ST_Pump :
STRUCT
    priority : INT;
    selection : BOOL;
    RunComd : BOOL;
END_STRUCT
END_TYPE

FUNCTION_BLOCK FB_P07
VAR_INPUT
    mode : BOOL;
    start : BOOL;
    stop : BOOL;
END_VAR
VAR_IN_OUT
    pumpGroup : ARRAY[1..5] OF ST_Pump;
END_VAR
VAR
    initialScans : INT := 0;
    enabled : BOOL := FALSE;
    i : INT;
    j : INT;
    higherCount : INT;
END_VAR

(* 每周期完整覆盖命令，避免继承调用前的外部命令。 *)
FOR i := 1 TO 5 DO
    pumpGroup[i].RunComd := FALSE;
END_FOR;

IF initialScans < 2 THEN
    initialScans := initialScans + 1;
    enabled := FALSE;
ELSE
    (* 停止为电平优先，并清除保持的启动许可。 *)
    IF stop THEN
        enabled := FALSE;
    ELSIF start THEN
        enabled := TRUE;
    END_IF;

    IF enabled AND NOT stop THEN
        IF NOT mode THEN
            (* 手动：仅所选泵获得运行命令。 *)
            FOR i := 1 TO 5 DO
                pumpGroup[i].RunComd := pumpGroup[i].selection;
            END_FOR;
        ELSE
            (*
            自动：计算每台泵之前的泵数。
            使用直接比较，不对 INT 优先级作减法，避免边界溢出。
            确定性的全序确保恰有三台排名在前三。
            *)
            FOR i := 1 TO 5 DO
                higherCount := 0;

                FOR j := 1 TO 5 DO
                    IF pumpGroup[j].priority > pumpGroup[i].priority THEN
                        higherCount := higherCount + 1;
                    ELSIF (pumpGroup[j].priority = pumpGroup[i].priority)
                          AND (j < i) THEN
                        higherCount := higherCount + 1;
                    END_IF;
                END_FOR;

                pumpGroup[i].RunComd := higherCount < 3;
            END_FOR;
        END_IF;
    END_IF;
END_IF;

END_FUNCTION_BLOCK
